<template>
  <transition name="view-composer-fade">
    <div v-if="open" class="view-composer-overlay" :class="{'is-museum-composer':embedded}" @click.self="closeComposer">
      <section class="view-composer" role="dialog" aria-modal="true" aria-labelledby="view-composer-title">
        <header>
          <div>
            <p>Compose a <AiViewTerm /></p>
            <h2 id="view-composer-title">What would you like to see?</h2>
          </div>
          <slot name="tools"/>
          <button v-if="!embedded" type="button" class="view-composer-close" aria-label="Close View composer" @click="closeComposer">
            <span>{{ busy ? 'Keep exploring' : 'Close' }}</span><span aria-hidden="true">&times;</span>
          </button>
        </header>

        <p class="view-composer-intro">Describe a question, theme, or perspective. The site&rsquo;s AI will bring relevant work together into a <AiViewTerm /> for you.</p>

        <form @submit.prevent="compose">
          <textarea
            id="view-composer-prompt"
            ref="prompt"
            v-model="prompt"
            aria-label="Describe the View you want"
            rows="3"
            maxlength="800"
            placeholder="Your question or perspective"
            :disabled="busy || externalComposeActive"
            @keydown.meta.enter.prevent="compose"
            @keydown.ctrl.enter.prevent="compose"
          ></textarea>

          <ViewComposeProgress v-if="busy" :started-at="composeStartedAt" :compact="compact" />

          <ViewComposeProgress
            v-else-if="externalComposeActive"
            :started-at="externalComposeStartedAt"
            :compact="compact"
          />

          <div v-else-if="message" class="view-composer-message" role="status">
            <strong>Try another angle</strong>
            <p>{{ message }}</p>
          </div>

          <footer>
            <span>⌘ Enter</span>
            <button type="submit" :disabled="busy || externalComposeActive || !prompt.trim()">
              <span>Compose <AiViewTerm /></span><ArrowUpRightIcon />
            </button>
          </footer>
        </form>
      </section>
    </div>
  </transition>
</template>

<script>
import ViewComposeProgress from './view/ViewComposeProgress.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import { candidatesForView } from '../utils/viewRetrieval';
import {
  beginViewCompose,
  cleanViewIntent,
  developViewDelay,
  DEVELOP_VIEW_LABEL,
  DEVELOP_VIEW_ROUTE,
  endViewCompose,
  isDevelopMode,
  isViewComposing,
  requestView,
  viewComposeState,
} from '../utils/viewSite';
import { sanitizeViewResponse, validateViewResponse } from '../utils/viewValidation';
import {
  addAskTurn,
  createAskSession,
  setAskOrigin,
  setAskView,
  recentDuplicateViewQuestion,
} from '../utils/askSession';

function sourceIds(view) {
  const ids = [];
  for (const section of view?.sections || []) {
    for (const block of section.blocks || []) {
      if (block?.source_id) ids.push(block.source_id);
      if (Array.isArray(block?.source_ids)) ids.push(...block.source_ids);
    }
  }
  return [...new Set(ids)];
}

export default {
  name: 'ViewComposer',
  components: { AiViewTerm, ViewComposeProgress },
  props: { embedded: Boolean, compact: Boolean, draftText: { type: String, default: '' } },
  emits: ['close', 'draft'],
  data() {
    return {
      open: false,
      prompt: this.draftText,
      busy: false,
      composeStartedAt: 0,
      message: '',
      controller: null,
    };
  },
  computed: {
    externalComposeActive() {
      return isViewComposing() && !this.busy;
    },
    externalComposeStartedAt() {
      return viewComposeState.startedAt;
    },
  },
  watch: { prompt(value) { if (this.embedded) this.$emit('draft', value); } },
  mounted() {
    if (this.embedded) this.openComposer();
    this._onKeydown = (event) => {
      if (event.key === 'Escape' && this.open) this.closeComposer();
    };
    window.addEventListener('keydown', this._onKeydown);
  },
  beforeUnmount() {
    this._unmounted = true;
    window.removeEventListener('keydown', this._onKeydown);
    if (!this.embedded) document.body.style.overflow = '';
  },
  methods: {
    openComposer() {
      this.open = true;
      this.message = '';
      if (!this.embedded) {
        document.body.style.overflow = 'hidden';
        this.$nextTick(() => this.$refs.prompt?.focus());
      }
    },
    closeComposer() {
      if (this.embedded) return;
      this.$emit('close');
      this.open = false;
      this.message = '';
      if (!this.embedded) document.body.style.overflow = '';
    },
    async compose() {
      const rawIntent = this.prompt.trim();
      const intent = cleanViewIntent(rawIntent);
      if (!intent || this.busy) return;
      if (isViewComposing()) {
        this.message = 'A View is already composing. Let it finish before composing another.';
        return;
      }
      this.controller?.abort();
      this.controller = new AbortController();
      this.busy = true;
      this.composeStartedAt = Date.now();
      this.message = '';
      beginViewCompose('views', this.composeStartedAt, intent);
      try {
        if (isDevelopMode(rawIntent)) {
          const fakeJob = {
            version: 1,
            jobId: `develop-${Date.now()}`,
            status: 'composing',
            message: DEVELOP_VIEW_LABEL,
            surface: 'views',
            originRoute: '/views',
            startedAt: Date.now(),
          };
          window.dispatchEvent(new CustomEvent('site-view-job', { detail: fakeJob }));
          await developViewDelay(this.controller.signal);
          if (this.controller.signal.aborted) throw new DOMException('Aborted', 'AbortError');
          window.dispatchEvent(new CustomEvent('site-view-job', {
            detail: { ...fakeJob, status: 'complete', completedAt: Date.now(), payload: null },
          }));
          if (this._unmounted || !this.open) {
            window.dispatchEvent(new CustomEvent('site-ai-complete', {
              detail: {
                kind: 'view',
                label: DEVELOP_VIEW_LABEL,
                originRoute: '/views',
                surface: 'views',
                route: DEVELOP_VIEW_ROUTE,
              },
            }));
          } else {
            if (!this.embedded) document.body.style.overflow = '';
            this.open = false;
            await this.$router.push({ path: DEVELOP_VIEW_ROUTE }).catch(() => {});
          }
          return;
        }
        if (recentDuplicateViewQuestion(intent)) {
          if (!this.embedded) document.body.style.overflow = '';
          this.open = false;
          await this.$router.push('/view').catch(() => {});
          return;
        }
        const sources = await candidatesForView({ message: intent, session: null, latestMessage: intent });
        const response = await requestView({
          message: intent,
          conversation: [],
          sources,
          meta: { surface: 'views', turn_index: 1 },
          signal: this.controller.signal,
        });
        const sanitized = sanitizeViewResponse(response, sources);
        const validation = validateViewResponse(sanitized, sources);
        if (!validation.ok) throw new Error(validation.error || 'The View could not be composed.');
        if (sanitized.action === 'answer') {
          this.message = validation.answer?.message || 'Describe a little more of what you would like to explore.';
          return;
        }
        const view = validation.view || sanitized.view;
        let session = createAskSession({ route: '/views' });
        session = addAskTurn(session, { role: 'user', text: intent, source_ids: [] });
        session = addAskTurn(session, { role: 'assistant', text: 'View composed.', source_ids: sourceIds(view) });
        session = setAskView(session, view);
        setAskOrigin(session, '/views');
        if (this._unmounted || !this.open) {
          // The visitor left the composer: the external job notice already
          // announced completion, so the "View ready" pill handles the entry.
          return;
        }
        if (!this.embedded) document.body.style.overflow = '';
        this.open = false;
        await this.$router.push('/view');
      } catch (error) {
        if (error?.name !== 'AbortError') {
          this.message = String(error?.message || 'Composition is temporarily unavailable. Please try again.').slice(0, 300);
        }
      } finally {
        endViewCompose('views');
        this.busy = false;
        this.composeStartedAt = 0;
        this.controller = null;
      }
    },
  },
};
</script>

